import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-C1WwKQnH.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/MySQL/04_%E8%BF%90%E7%BB%B4%E7%AF%87/03_%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98.html","title":"性能调优","lang":"zh-CN","frontmatter":{"title":"性能调优","icon":"fa6-solid:gauge-high","order":3,"category":["数据库","MySQL"],"tag":["MySQL","性能调优","慢查询","Performance Schema","参数优化"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":7.88,"words":2365},"filePathRelative":"后端开发/数据库/MySQL/04_运维篇/03_性能调优.md"}`),s={name:`03_性能调优.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="性能调优" tabindex="-1"><a class="header-anchor" href="#性能调优"><span>性能调优</span></a></h1><p>数据库性能问题 80% 来自糟糕的 SQL 和缺失的索引，20% 来自参数配置不当。系统化的调优方法论比&quot;盲猜参数&quot;更有效：先定位瓶颈，再对症下药。</p><blockquote><p>参考资料：<a href="https://xiaolincoding.com/mysql/base/innodb.html" target="_blank" rel="noopener noreferrer">小林coding - MySQL 调优</a> | <a href="https://dev.mysql.com/doc/refman/8.0/en/optimization.html" target="_blank" rel="noopener noreferrer">MySQL 官方文档 - Optimization</a></p></blockquote><h2 id="_1-慢查询日志" tabindex="-1"><a class="header-anchor" href="#_1-慢查询日志"><span>1. 慢查询日志</span></a></h2><p>慢查询日志是 MySQL 调优的起点，记录执行时间超过阈值的 SQL。</p><h3 id="_1-1-开启与配置" tabindex="-1"><a class="header-anchor" href="#_1-1-开启与配置"><span>1.1 开启与配置</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 开启慢查询日志</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> slow_query_log </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 设置阈值（秒）</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> long_query_time </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 超过1秒的查询记录</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 慢查询日志文件路径</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;slow_query_log_file&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 是否记录未使用索引的查询</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> log_queries_not_using_indexes </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每分钟记录未使用索引查询的最大数量（防止日志暴增）</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> log_throttle_queries_not_using_indexes </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 60</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 记录管理语句（ALTER、ANALYZE 等）</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> log_slow_admin_statements </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-分析慢查询" tabindex="-1"><a class="header-anchor" href="#_1-2-分析慢查询"><span>1.2 分析慢查询</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 mysqldumpslow 快速分析</span></span>
<span class="line"><span style="color:#61AFEF;">mysqldumpslow</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> t</span><span style="color:#D19A66;"> -t</span><span style="color:#D19A66;"> 10</span><span style="color:#98C379;"> /var/log/mysql/slow.log</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># -s t: 按查询时间排序</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># -t 10: 显示前10条</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 pt-query-digest（更强大）</span></span>
<span class="line"><span style="color:#61AFEF;">pt-query-digest</span><span style="color:#98C379;"> /var/log/mysql/slow.log</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">slow_report.txt</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># pt-query-digest 输出示例</span></span>
<span class="line"><span># Rank Query ID           Response time  Calls</span></span>
<span class="line"><span># ==== ================== ============== =====</span></span>
<span class="line"><span>#    1 0x5A1C6B2D3E4F...  120.4567 62.1%  3421</span></span>
<span class="line"><span>#    2 0x7B8C9D0E1F2A...   45.1234 23.3%  1523</span></span>
<span class="line"><span>#    3 0x9C0D1E2F3A4B...   15.6789  8.1%   892</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">慢查询日志大小控制</p><ul><li>生产环境 long_query_time 建议 0.1~1 秒</li><li>日志文件定期轮转，避免磁盘占满</li><li>使用 <code>pt-query-digest --review</code> 将分析结果持久化到数据库</li></ul></div><h2 id="_2-performance-schema" tabindex="-1"><a class="header-anchor" href="#_2-performance-schema"><span>2. Performance Schema</span></a></h2><p>Performance Schema 是 MySQL 内置的性能监控引擎，低开销地收集服务器运行数据。</p><h3 id="_2-1-核心监控表" tabindex="-1"><a class="header-anchor" href="#_2-1-核心监控表"><span>2.1 核心监控表</span></a></h3><table><thead><tr><th>表</th><th>监控内容</th></tr></thead><tbody><tr><td>events_waits_current</td><td>当前等待事件</td></tr><tr><td>events_waits_history</td><td>最近等待事件</td></tr><tr><td>events_statements_current</td><td>当前执行的语句</td></tr><tr><td>events_statements_history</td><td>最近执行的语句</td></tr><tr><td>file_summary_by_instance</td><td>文件 IO 统计</td></tr><tr><td>memory_summary_by_thread</td><td>线程内存使用</td></tr></tbody></table><h3 id="_2-2-常用查询" tabindex="-1"><a class="header-anchor" href="#_2-2-常用查询"><span>2.2 常用查询</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前正在等待的事件</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    EVENT_NAME,</span></span>
<span class="line"><span style="color:#ABB2BF;">    TIMER_WAIT / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;等待时间(ms)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    SOURCE</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">events_waits_current</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> TIMER_WAIT </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 1000000000</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 超过1秒</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看 IO 瓶颈</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    FILE_NAME,</span></span>
<span class="line"><span style="color:#ABB2BF;">    COUNT_READ,</span></span>
<span class="line"><span style="color:#ABB2BF;">    COUNT_WRITE,</span></span>
<span class="line"><span style="color:#ABB2BF;">    SUM_TIMER_READ / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;读耗时(ms)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    SUM_TIMER_WRITE / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;写耗时(ms)&#39;</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">file_summary_by_instance</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> SUM_TIMER_READ + SUM_TIMER_WRITE </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看最耗时的 SQL</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    DIGEST_TEXT </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;SQL&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    COUNT_STAR </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;执行次数&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    SUM_TIMER_WAIT / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;总耗时(ms)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    AVG_TIMER_WAIT / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;平均耗时(ms)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    MAX_TIMER_WAIT / </span><span style="color:#D19A66;">1000000000</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;最大耗时(ms)&#39;</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">events_statements_summary_by_digest</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> SUM_TIMER_WAIT </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-内存监控" tabindex="-1"><a class="header-anchor" href="#_2-3-内存监控"><span>2.3 内存监控</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看各线程的内存使用</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    THREAD_ID,</span></span>
<span class="line"><span style="color:#ABB2BF;">    EVENT_NAME,</span></span>
<span class="line"><span style="color:#ABB2BF;">    CURRENT_NUMBER_OF_BYTES_USED / </span><span style="color:#D19A66;">1024</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1024</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;当前使用(MB)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    HIGH_NUMBER_OF_BYTES_USED / </span><span style="color:#D19A66;">1024</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1024</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;峰值(MB)&#39;</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">memory_summary_by_thread_by_event_name</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CURRENT_NUMBER_OF_BYTES_USED </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 1048576</span><span style="color:#7F848E;font-style:italic;">  -- &gt; 1MB</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> CURRENT_NUMBER_OF_BYTES_USED </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-sys-schema" tabindex="-1"><a class="header-anchor" href="#_3-sys-schema"><span>3. Sys Schema</span></a></h2><p>Sys Schema 是 Performance Schema 的友好视图，开箱即用：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Top 10 最耗时的 SQL</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statements_with_runtimes_in_95th_percentile</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 未使用索引的查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">statements_with_full_table_scans</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 冗余索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schema_unused_indexes</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 冗余索引（更详细）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schema_redundant_indexes</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 表 IO 统计</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    table_schema,</span></span>
<span class="line"><span style="color:#ABB2BF;">    table_name,</span></span>
<span class="line"><span style="color:#ABB2BF;">    rows_fetched,</span></span>
<span class="line"><span style="color:#ABB2BF;">    rows_inserted,</span></span>
<span class="line"><span style="color:#ABB2BF;">    rows_updated,</span></span>
<span class="line"><span style="color:#ABB2BF;">    rows_deleted,</span></span>
<span class="line"><span style="color:#ABB2BF;">    io_read / </span><span style="color:#D19A66;">1024</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1024</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;读MB&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    io_write / </span><span style="color:#D19A66;">1024</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1024</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;写MB&#39;</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schema_table_statistics_with_buffer</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> io_read + io_write </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话连接统计</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">session</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> command </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Query&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> timer_wait </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">定期清理冗余索引</p><ul><li>冗余索引浪费存储，增加写入开销</li><li>优化器可能选错索引</li><li>用 <code>sys.schema_unused_indexes</code> 识别，确认安全后删除</li></ul></div><h2 id="_4-核心参数优化" tabindex="-1"><a class="header-anchor" href="#_4-核心参数优化"><span>4. 核心参数优化</span></a></h2><h3 id="_4-1-关键参数一览" tabindex="-1"><a class="header-anchor" href="#_4-1-关键参数一览"><span>4.1 关键参数一览</span></a></h3><table><thead><tr><th>参数</th><th>推荐值</th><th>说明</th></tr></thead><tbody><tr><td>innodb_buffer_pool_size</td><td>物理内存 60%~80%</td><td>最重要的参数</td></tr><tr><td>innodb_buffer_pool_instances</td><td>4~8（&gt;1GB时）</td><td>减少锁竞争</td></tr><tr><td>innodb_io_capacity</td><td>SSD:10000~20000, HDD:200~400</td><td>刷脏速度</td></tr><tr><td>innodb_io_capacity_max</td><td>innodb_io_capacity × 2</td><td>刷脏上限</td></tr><tr><td>innodb_flush_log_at_trx_commit</td><td>1（主库）</td><td>事务持久性</td></tr><tr><td>sync_binlog</td><td>1（主库）</td><td>Binlog 持久性</td></tr><tr><td>max_connections</td><td>500~2000</td><td>最大连接数</td></tr><tr><td>innodb_lock_wait_timeout</td><td>10~30</td><td>锁等待超时（秒）</td></tr><tr><td>innodb_deadlock_detect</td><td>ON</td><td>死锁检测</td></tr><tr><td>innodb_print_all_deadlocks</td><td>ON</td><td>记录死锁日志</td></tr><tr><td>innodb_sort_buffer_size</td><td>2M~8M</td><td>排序缓冲区</td></tr><tr><td>join_buffer_size</td><td>4M~16M</td><td>JOIN 缓冲区</td></tr><tr><td>sort_buffer_size</td><td>2M~8M</td><td>ORDER BY 缓冲区</td></tr><tr><td>innodb_thread_concurrency</td><td>0（默认，不限）</td><td>并发线程数</td></tr></tbody></table><h3 id="_4-2-buffer-pool-配置" tabindex="-1"><a class="header-anchor" href="#_4-2-buffer-pool-配置"><span>4.2 Buffer Pool 配置</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 32GB 内存服务器的推荐配置</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_buffer_pool_size </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 25769803776</span><span style="color:#ABB2BF;">;     </span><span style="color:#7F848E;font-style:italic;">-- 24GB</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_buffer_pool_instances </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 8</span><span style="color:#ABB2BF;">;           </span><span style="color:#7F848E;font-style:italic;">-- 8个实例</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_old_blocks_pct </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 37</span><span style="color:#ABB2BF;">;                 </span><span style="color:#7F848E;font-style:italic;">-- Old区3/8</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_old_blocks_time </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1000</span><span style="color:#ABB2BF;">;              </span><span style="color:#7F848E;font-style:italic;">-- 1秒晋升窗口</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-io-相关配置" tabindex="-1"><a class="header-anchor" href="#_4-3-io-相关配置"><span>4.3 IO 相关配置</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SSD 磁盘推荐</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_io_capacity </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_io_capacity_max </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 20000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_flush_method </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> O_DIRECT;  </span><span style="color:#7F848E;font-style:italic;">-- 绕过OS缓存</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- HDD 磁盘推荐</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_io_capacity </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 200</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_io_capacity_max </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 400</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">innodb_flush_method = O_DIRECT</p><ul><li>O_DIRECT 绕过操作系统文件缓存，避免 Doublewrite</li><li>适用于 Buffer Pool 较大（&gt;4GB）的场景</li><li>如果 Buffer Pool 较小，O_DIRECT 反而降低性能</li></ul></div><h2 id="_5-连接池调优" tabindex="-1"><a class="header-anchor" href="#_5-连接池调优"><span>5. 连接池调优</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前连接数</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW </span><span style="color:#C678DD;">STATUS</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;Threads_connected&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW </span><span style="color:#C678DD;">STATUS</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;Max_used_connections&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看连接配置</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;max_connections&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;wait_timeout&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;interactive_timeout&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 推荐配置</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> max_connections </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> wait_timeout </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 28800</span><span style="color:#ABB2BF;">;        </span><span style="color:#7F848E;font-style:italic;">-- 8小时</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> interactive_timeout </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 28800</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> max_connect_errors </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">;    </span><span style="color:#7F848E;font-style:italic;">-- 防止暴力破解</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># HikariCP 连接池配置（Java 应用推荐）</span></span>
<span class="line"><span style="color:#E06C75;">spring</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  datasource</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    hikari</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      maximum-pool-size</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">20</span><span style="color:#7F848E;font-style:italic;">          # 连接池大小 = CPU核心数 × 2 + 磁盘数</span></span>
<span class="line"><span style="color:#E06C75;">      minimum-idle</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">5</span><span style="color:#7F848E;font-style:italic;">                # 最小空闲连接</span></span>
<span class="line"><span style="color:#E06C75;">      connection-timeout</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">30000</span><span style="color:#7F848E;font-style:italic;">      # 获取连接超时30秒</span></span>
<span class="line"><span style="color:#E06C75;">      idle-timeout</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">600000</span><span style="color:#7F848E;font-style:italic;">           # 空闲连接超时10分钟</span></span>
<span class="line"><span style="color:#E06C75;">      max-lifetime</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">1800000</span><span style="color:#7F848E;font-style:italic;">          # 连接最大存活30分钟</span></span>
<span class="line"><span style="color:#E06C75;">      connection-test-query</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">SELECT 1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">连接数不是越多越好</p><ul><li>每个连接消耗约 2~5MB 内存（sort_buffer + join_buffer 等）</li><li>1000 个连接可能消耗 2~5GB 内存</li><li>连接池大小建议：CPU 核心数 × 2 + 有效磁盘数</li></ul></div><h2 id="_6-query-cache-已移除" tabindex="-1"><a class="header-anchor" href="#_6-query-cache-已移除"><span>6. Query Cache（已移除）</span></a></h2><p>MySQL 8.0 正式移除了 Query Cache，原因：</p><table><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td>全局锁</td><td>查询缓存使用全局互斥锁，高并发下成为瓶颈</td></tr><tr><td>失效频繁</td><td>任何表的数据变化都导致该表所有缓存失效</td></tr><tr><td>命中率低</td><td>生产环境命中率通常 &lt; 20%</td></tr><tr><td>内存浪费</td><td>缓存占用 Buffer Pool 空间</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">8.0 不再有 Query Cache</p><ul><li>5.7 可设置 <code>query_cache_type = OFF</code> 禁用</li><li>8.0 已完全移除相关参数</li><li>替代方案：应用层缓存（Redis/Memcached）</li></ul></div><h2 id="_7-pt-工具集" tabindex="-1"><a class="header-anchor" href="#_7-pt-工具集"><span>7. PT 工具集</span></a></h2><p>Percona Toolkit 是 MySQL DBA 的瑞士军刀：</p><h3 id="_7-1-pt-query-digest" tabindex="-1"><a class="header-anchor" href="#_7-1-pt-query-digest"><span>7.1 pt-query-digest</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 分析慢查询日志</span></span>
<span class="line"><span style="color:#61AFEF;">pt-query-digest</span><span style="color:#98C379;"> /var/log/mysql/slow.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 分析 Processlist</span></span>
<span class="line"><span style="color:#61AFEF;">pt-query-digest</span><span style="color:#D19A66;"> --processlist</span><span style="color:#98C379;"> h=127.0.0.1,u=root,p=xxx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将分析结果存入数据库</span></span>
<span class="line"><span style="color:#61AFEF;">pt-query-digest</span><span style="color:#D19A66;"> --review</span><span style="color:#98C379;"> h=127.0.0.1,D=test,t=query_review</span><span style="color:#98C379;"> slow.log</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-pt-index-usage" tabindex="-1"><a class="header-anchor" href="#_7-2-pt-index-usage"><span>7.2 pt-index-usage</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 分析慢查询日志，找出未使用的索引</span></span>
<span class="line"><span style="color:#61AFEF;">pt-index-usage</span><span style="color:#98C379;"> /var/log/mysql/slow.log</span><span style="color:#D19A66;"> --host=127.0.0.1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出 DROP INDEX 语句</span></span>
<span class="line"><span style="color:#61AFEF;">pt-index-usage</span><span style="color:#98C379;"> slow.log</span><span style="color:#D19A66;"> --host=127.0.0.1</span><span style="color:#D19A66;"> --drop-all</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-其他常用工具" tabindex="-1"><a class="header-anchor" href="#_7-3-其他常用工具"><span>7.3 其他常用工具</span></a></h3><table><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>pt-online-schema-change</td><td>在线 DDL，不锁表</td></tr><tr><td>pt-table-checksum</td><td>主从数据一致性校验</td></tr><tr><td>pt-table-sync</td><td>修复主从数据不一致</td></tr><tr><td>pt-archiver</td><td>归档旧数据</td></tr><tr><td>pt-deadlock-logger</td><td>死锁监控</td></tr><tr><td>pt-mysql-summary</td><td>MySQL 配置摘要</td></tr></tbody></table><h2 id="_8-真实案例-从-10s-到-50ms" tabindex="-1"><a class="header-anchor" href="#_8-真实案例-从-10s-到-50ms"><span>8. 真实案例：从 10s 到 50ms</span></a></h2><h3 id="场景" tabindex="-1"><a class="header-anchor" href="#场景"><span>场景</span></a></h3><p>一个订单系统的查询，按日期范围 + 状态筛选，执行时间 10 秒：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 原始查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;2025-06-30&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#C678DD;"> status</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;PAID&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;SHIPPED&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#ABB2BF;"> region </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;EAST&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="优化过程" tabindex="-1"><a class="header-anchor" href="#优化过程"><span>优化过程</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 1: EXPLAIN 分析</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;2025-06-30&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#C678DD;"> status</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;PAID&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;SHIPPED&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#ABB2BF;"> region </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;EAST&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：type=ALL，rows=5000000，Using where; Using filesort</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 问题：全表扫描 + 文件排序</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 2: 添加复合索引</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">ADD</span><span style="color:#C678DD;"> INDEX</span><span style="color:#ABB2BF;"> idx_region_status_created (region, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 3: 再次 EXPLAIN</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：type=range，rows=50000，Using index condition</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行时间：2秒（有改善但不够）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 4: 覆盖索引优化（避免回表）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, order_no, created_at, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> region </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;EAST&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#C678DD;"> status</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;PAID&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;SHIPPED&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#98C379;"> &#39;2025-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;2025-06-30&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：Using index，执行时间 50ms</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 5: 进一步优化 - 调整 Buffer Pool</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 确保热数据在内存中</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_buffer_pool_size </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 17179869184</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 16GB</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Step 6: 验证 Buffer Pool 命中率</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> - (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">           WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Innodb_buffer_pool_reads&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">         / (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">            WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Innodb_buffer_pool_read_requests&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    ) * </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> AS</span><span style="color:#98C379;"> &#39;命中率%&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：99.97%</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="优化总结" tabindex="-1"><a class="header-anchor" href="#优化总结"><span>优化总结</span></a></h3>`,57),r(d,{code:`eJxLL0osyFDwCeJSAALHaKWnrSteLFzxrHP1s/5+m6QifTtDg2KlWAVdXTsFJ6Dskt6nEzqeb1n0dM9UsKwRUBKs1QmsxDla6cWytuezpyEpMTXIhSlyBityiVZyKk1LSy1SCMjPz1F4saH5yZ4ZYKXGEKVgtcUllTmpCo4KaZk5OVbKbiYmxsZmOsn5OflFVsppaWlIapxgatwsLQwMsKtxhqoxcXZ0M8WhxgWqxsjQ0szNGFkNALmOYk8=`}),o[1]||=i(`<table><thead><tr><th>阶段</th><th>优化手段</th><th>耗时</th><th>提升倍数</th></tr></thead><tbody><tr><td>原始</td><td>无索引</td><td>10s</td><td>-</td></tr><tr><td>加索引</td><td>复合索引</td><td>2s</td><td>5x</td></tr><tr><td>覆盖索引</td><td>避免回表</td><td>50ms</td><td>200x</td></tr><tr><td>Buffer Pool</td><td>内存命中率</td><td>30ms</td><td>333x</td></tr></tbody></table><h2 id="_9-使用-dbeaver-辅助调优" tabindex="-1"><a class="header-anchor" href="#_9-使用-dbeaver-辅助调优"><span>9. 使用 dbeaver 辅助调优</span></a></h2><p>在 <a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">dbeaver</a> 中可以方便地进行性能调优：</p><ol><li><strong>执行计划分析</strong>：SQL 编辑器中点击 <strong>Explain Plan</strong> 查看执行计划</li><li><strong>慢查询定位</strong>：使用 SQL 编辑器执行 <code>sys.statements_with_runtimes_in_95th_percentile</code></li><li><strong>索引管理</strong>：右键表 → <strong>Edit Table</strong> → <strong>Indexes</strong> 选项卡</li><li><strong>Schema 对比</strong>：使用 dbeaver 的 Compare 功能对比不同环境的表结构</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 在 dbeaver 中一键查看数据库健康状态</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">     WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Innodb_buffer_pool_read_requests&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;逻辑读&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">     WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Innodb_buffer_pool_reads&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;磁盘读&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">     WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Threads_connected&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;当前连接&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">     WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Slow_queries&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;慢查询数&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> VARIABLE_VALUE </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">global_status</span></span>
<span class="line"><span style="color:#C678DD;">     WHERE</span><span style="color:#ABB2BF;"> VARIABLE_NAME </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Innodb_row_lock_waits&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#98C379;"> &#39;锁等待次数&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_10-面试技巧" tabindex="-1"><a class="header-anchor" href="#_10-面试技巧"><span>10. 面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>如何定位慢查询？</strong></p><ul><li>开启慢查询日志，用 pt-query-digest 分析</li><li>结合 Performance Schema 和 Sys Schema 定位瓶颈</li></ul></li><li><p><strong>innodb_buffer_pool_size 设多大？</strong></p><ul><li>物理内存的 60%~80%</li><li>专用数据库服务器可以设到 80%</li><li>留足内存给 OS 和其他进程</li></ul></li><li><p><strong>如何优化一条慢 SQL？</strong></p><ul><li>EXPLAIN 分析执行计划</li><li>添加合适的索引（复合索引、覆盖索引）</li><li>避免回表、文件排序、临时表</li><li>优化 SQL 写法（避免 SELECT *、子查询改 JOIN）</li></ul></li><li><p><strong>sync_binlog 和 innodb_flush_log_at_trx_commit 怎么设？</strong></p><ul><li>主库必须双1（sync_binlog=1, flush_log_at_trx_commit=1）</li><li>从库可以放松（sync_binlog=0, flush_log_at_trx_commit=2）</li></ul></li><li><p><strong>Query Cache 为什么被移除？</strong></p><ul><li>全局互斥锁成为并发瓶颈</li><li>缓存命中率低、失效频繁</li><li>8.0 已完全移除，用应用层缓存替代</li></ul></li></ol></div><hr><blockquote><p>本文参考了 <a href="https://xiaolincoding.com/mysql/base/innodb.html" target="_blank" rel="noopener noreferrer">小林coding</a> 和 <a href="https://dev.mysql.com/doc/refman/8.0/en/optimization.html" target="_blank" rel="noopener noreferrer">MySQL 8.0 官方文档</a>。推荐使用 <a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">dbeaver</a> 辅助性能分析和调优。</p></blockquote>`,9)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};